import React, { useEffect, useState } from "react";
import axios from "axios";
import "./Page.css";

function Internships() {

const [jobs,setJobs]=useState([]);
const [year,setYear]=useState("");
const [branch,setBranch]=useState("");

useEffect(()=>{

axios.get("http://localhost:5000/api/jobs")
.then(res=>{

const internships=res.data.filter(
j=>j.jobType==="Internship"
);

setJobs(internships);

});

},[]);


const filtered=jobs.filter(job=>{

return(

(year==="" || job.eligibleYears?.includes(year)) &&
(branch==="" || job.branch?.includes(branch))

)

});


return (

<div className="page">

<h1 className="title">
Internship Opportunities
</h1>

<p className="subtitle">
Discover internships tailored to your branch and academic year
</p>


<div className="filters">

<select onChange={e=>setYear(e.target.value)}>
<option value="">All Years</option>
<option value="1st">1st Year</option>
<option value="2nd">2nd Year</option>
<option value="3rd">3rd Year</option>
<option value="4th">4th Year</option>
</select>


<select onChange={e=>setBranch(e.target.value)}>
<option value="">All Branches</option>
<option value="CSE">CSE</option>
<option value="IT">IT</option>
<option value="ECE">ECE</option>
<option value="EEE">EEE</option>
<option value="MECH">MECH</option>
<option value="CIVIL">CIVIL</option>
</select>

</div>


<div className="grid">

{filtered.map(job=>(

<div className="card" key={job.jobId}>

<div className="cardTop">

<h3>{job.title}</h3>

<h4>{job.company}</h4>

</div>

<p className="location">
📍 {job.location || "India"}
</p>

<p className="tag">
Internship
</p>

<p className="info">
<b>Eligible:</b> {job.eligibleYears?.join(", ")}
</p>

<p className="info">
<b>Branch:</b> {job.branch?.join(", ")}
</p>

<a
className="applyBtn"
href={job.applyLink}
target="_blank"
rel="noreferrer"
>
Apply Now
</a>

</div>

))}

</div>

</div>

);

}

export default Internships;
